Repair the following complete source and return a corrected complete TypeScript source file. Preserve the exported API.

`CrateRegistry` stores crates by exact, case-sensitive `id`. `create` throws `new Error("Duplicate id")` for an existing ID. `get` returns a deep copy or `undefined`. `list` returns deep copies in insertion order. `patch` changes only supplied fields, throws `new Error("Not found")` for a missing ID, and must not retain aliases to the patch object. Supplying an empty patch is valid. `replace` preserves the requested ID regardless of `value.id`, keeps the crate's existing list position, and stores a deep copy. `remove` reports whether an entry existed. Caller mutations of inputs or returned values must never affect stored state. Tags preserve their order, duplicates, and empty strings.

```typescript
export interface Crate {
  id: string;
  label: string;
  capacity: number;
  tags: string[];
}

export type CratePatch = Partial<Omit<Crate, "id">>;

function copy(crate: Crate): Crate {
  return {...crate, tags: [...crate.tags]};
}

export class CrateRegistry {
  private readonly crates = new Map<string, Crate>();

  public create(crate: Crate): Crate {
    if (this.crates.has(crate.id)) throw new Error("Duplicate id");
    const stored = copy(crate);
    this.crates.set(stored.id, stored);
    return copy(stored);
  }

  public get(id: string): Crate | undefined {
    const crate = this.crates.get(id);
    return crate === undefined ? undefined : copy(crate);
  }

  public list(): Crate[] {
    return Array.from(this.crates.values(), copy);
  }

  public patch(id: string, patch: CratePatch): Crate {
    const current = this.crates.get(id);
    if (current === undefined) throw new Error("Not found");
    const updated: Crate = {...current, ...patch, id};
    this.crates.set(id, updated);
    return copy(updated);
  }

  public replace(id: string, value: Crate): Crate {
    if (!this.crates.has(id)) throw new Error("Not found");
    const stored = copy({...value, id});
    this.crates.set(id, stored);
    return copy(stored);
  }

  public remove(id: string): boolean {
    return this.crates.delete(id);
  }
}
```

