import { CrateRegistry, type Crate } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(message);
}

function expectError(action: () => unknown, expected: string): void {
  let caught: unknown;
  try { action(); } catch (error) { caught = error; }
  assert(caught instanceof Error, `expected error: ${expected}`);
  if (caught instanceof Error) equal(caught.message, expected, "error message should match");
}

const registry = new CrateRegistry();
equal(registry.get("missing"), undefined, "missing get should return undefined");
equal(registry.list().length, 0, "new registry should be empty");
equal(registry.remove("missing"), false, "removing missing id should return false");
expectError(() => registry.patch("missing", {}), "Not found");
expectError(() => registry.replace("missing", { id: "x", label: "x", capacity: 1, tags: [] }), "Not found");

const input: Crate = { id: "A", label: "first", capacity: 0, tags: ["", "tag", "tag"] };
const created = registry.create(input);
assert(created !== input, "create result must be a copy");
assert(created.tags !== input.tags, "create result tags must be copied");
input.label = "mutated input";
input.tags.push("mutated input");
created.label = "mutated result";
created.tags[0] = "mutated result";

const storedA = registry.get("A");
assert(storedA !== undefined, "created crate should be retrievable");
if (storedA !== undefined) {
  equal(storedA.label, "first", "caller mutations must not affect stored label");
  equal(storedA.capacity, 0, "zero capacity must be preserved");
  equal(storedA.tags.join("|"), "|tag|tag", "empty and duplicate tags must be preserved");
}
expectError(() => registry.create({ id: "A", label: "duplicate", capacity: 2, tags: [] }), "Duplicate id");
registry.create({ id: "a", label: "lowercase", capacity: 1, tags: [] });
registry.create({ id: "B", label: "second", capacity: 2, tags: ["b"] });
equal(registry.list().length, 3, "ids should be case-sensitive");

const emptyPatch = registry.patch("A", {});
equal(emptyPatch.label, "first", "empty patch should preserve fields");
const patchTags = ["new", "", "new"];
const patched = registry.patch("A", { label: "patched", tags: patchTags });
patchTags.push("external");
patched.tags[0] = "returned mutation";
const afterPatch = registry.get("A");
assert(afterPatch !== undefined, "patched crate should remain retrievable");
if (afterPatch !== undefined) {
  equal(afterPatch.id, "A", "patch must preserve id");
  equal(afterPatch.label, "patched", "supplied field should change");
  equal(afterPatch.capacity, 0, "unsupplied field should remain unchanged");
  equal(afterPatch.tags.join("|"), "new||new", "patch tags must be copied and preserve order");
}

const replacement: Crate = { id: "WRONG", label: "replacement", capacity: 9, tags: ["r", "r", ""] };
const replaced = registry.replace("A", replacement);
equal(replaced.id, "A", "replace must preserve requested id");
replacement.label = "external";
replacement.tags.reverse();
replaced.tags.push("returned");

const listed = registry.list();
equal(listed[0].id, "A", "replace must preserve existing insertion position");
equal(listed[1].id, "a", "later lowercase id should retain position");
equal(listed[2].id, "B", "later id should retain position");
equal(listed[0].label, "replacement", "replace must store copied value");
equal(listed[0].tags.join("|"), "r|r|", "replace tags must be deeply copied");
listed[0].label = "list mutation";
listed[0].tags.push("list mutation");
const listedAgain = registry.list();
assert(listedAgain !== listed, "each list result array must be fresh");
assert(listedAgain[0] !== listed[0], "list entries must be fresh copies");
assert(listedAgain[0].tags !== listed[0].tags, "list tags must be fresh copies");
equal(listedAgain[0].label, "replacement", "mutating list result must not affect storage");

const getOne = registry.get("A");
const getTwo = registry.get("A");
assert(getOne !== undefined && getTwo !== undefined, "existing crate should be returned");
if (getOne !== undefined && getTwo !== undefined) {
  assert(getOne !== getTwo && getOne.tags !== getTwo.tags, "each get must return a fresh deep copy");
}

equal(registry.remove("a"), true, "remove should report existing entry");
equal(registry.remove("a"), false, "second remove should report missing entry");
equal(registry.get("a"), undefined, "removed exact id should be absent");
assert(registry.get("A") !== undefined, "removing lowercase id must not remove uppercase id");

